const $ = (sel) => document.querySelector(sel);

const examples = [
  "Σινωπίτης","Ἰοπίτης","Ἀκεσίτης","Παγασίτης","Ἀκμονίτης","Ἀβδηρίτης","Γαβαλίτης","Διολκίτης","Μεμφίτης","Ναυκρατίτης",
  "εὐρείτης","βαθυρρείτης","ἀκαλαρείτης","ἱερείτης","Σαμαρείτης","Ἀταρνείτης","Ἑλείτης","Ἁγνωνείτης","Μαρωνείτης","Καυκωνείτης",
  "Δικαιαρχείτης","Ζελείτης","Ὠρείτης","ἀλείτης","ἀλοίτης",
  "τραπεζίτης","τραπεζείτης","τραπεζήτης",
  "πρεσβύτης","ἐλύτης","βασανύτης","ἁλκυονύτης","Ἀρχύτης","Πιδύτης","Αἰγύτης","Κωβρύτης","Μωλύτης","Αἰπύτης","Πατρασύτης",
  "Δαμοίτης","Μενοίτης","Θυμοίτης","Ἀγροίτης","Φιλοίτης","Λαοίτης","Ἀνεμοίτης","Ὀροίτης","Ἀνδροίτης","Σακοίτης","Ζιποίτης",
  "Βουτοίτης","Σαβοίτης","Κυβοίτης",
  "Μαντούτης","τριακοντούτης",
  "ὑφάντης","ἀγύρτης","εὐφράντης","ὀξύντης","ἐγέρτης","ὀρίντης","αὐθέντης","Λαέρτης","Σιβύρτης","Βερεκύντης"
];

// --- Polytonic helpers (approximate) ---
const COMBINING = /[\u0300-\u036f]/g;
function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripDiacritics(s){
  // remove combining marks; keep base letters
  return nfc(nfd(s).replace(COMBINING, ''));
}

function lowerGreek(s){
  return s.toLocaleLowerCase('el');
}

function endsWithAny(word, suffixes){
  for(const suf of suffixes){
    if(word.endsWith(suf)) return suf;
  }
  return null;
}

// Very rough syllabifier: split before vowel groups.
const VOW = "αεηιουω";
function isVowel(ch){ return VOW.includes(ch); }
function roughSyllables(word){
  const w = stripDiacritics(lowerGreek(word)).replace(/[^\p{L}]/gu,'');
  if(!w) return [];
  // Build chunks: onset+vowelgroup+coda until next vowelgroup
  let syl = [];
  let cur = "";
  let i=0;
  while(i<w.length){
    cur += w[i];
    // if current char is vowel, absorb following vowels (diphthong-ish)
    if(isVowel(w[i])){
      while(i+1<w.length && isVowel(w[i+1])){ cur += w[i+1]; i++; }
      // then absorb following consonants up to (but not including) next vowel
      while(i+1<w.length && !isVowel(w[i+1])){
        // stop if next-next is vowel: leave one consonant for onset (very rough)
        if(i+2<w.length && isVowel(w[i+2])) break;
        cur += w[i+1]; i++;
      }
      syl.push(cur);
      cur = "";
    }
    i++;
  }
  if(cur) syl.push(cur);
  return syl.filter(x=>x.length);
}

// Accent placement: add acute to first vowel of target syllable.
const ACUTE_MAP = {
  'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
  'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
};
function addAcuteToFirstVowel(s){
  // operate on NFC Greek; if already has tonos/polytonic, we still try after stripping
  const base = stripDiacritics(s);
  let out = "";
  let done = false;
  for(const ch of base){
    if(!done && ACUTE_MAP[ch]){ out += ACUTE_MAP[ch]; done = true; }
    else out += ch;
  }
  return out;
}

function barytoneSuggest(word){
  const clean = stripDiacritics(word);
  const syl = roughSyllables(clean);
  if(syl.length === 0) return {suggestion: word, target: null, syl};
  // barytone: not final. Prefer penult; if monosyllable, keep as is.
  const targetIndex = syl.length >= 2 ? syl.length-2 : 0;
  const rebuilt = syl.map((s,i)=> i===targetIndex ? addAcuteToFirstVowel(s) : s).join('');
  return {suggestion: rebuilt, target: targetIndex, syl};
}

function classify(word){
  const w = stripDiacritics(lowerGreek(word)).replace(/\s+/g,'');
  const suf = endsWithAny(w, ["οιτης","ουτης","υτης","ειτης","ιτης","της"]);
  let cls = {suffix:suf, barytone:null, note:[]};

  if(!suf){
    cls.barytone = null;
    cls.note.push("No -της-type ending detected.");
    return cls;
  }

  if(suf === "οιτης"){
    cls.barytone = true;
    cls.note.push("Matches -οιτης: Herodian says isosyllabic -οιτης forms are barytone.");
  } else if(suf === "ουτης"){
    cls.barytone = true;
    cls.note.push("Matches -ουτης: Herodian says -ουτης forms are barytone.");
  } else if(suf === "υτης"){
    cls.barytone = true;
    cls.note.push("Matches -υτης: Herodian says derivatives with long υ are barytone (toy assumes your -υτης is in that class).");
  } else if(suf === "ειτης"){
    cls.barytone = true;
    cls.note.push("Matches -ειτης (as in many place/ethnic forms listed): often treated as barytone in this passage’s examples.");
  } else if(suf === "ιτης"){
    cls.barytone = true;
    cls.note.push("Matches -ιτης (e.g. Σινωπίτης): many such ethnics in the list behave barytone in practice.");
  } else if(suf === "της"){
    cls.barytone = true;
    cls.note.push("Matches plain -της: Herodian gives a barytone rule for certain -της words (non-participial; penult ending in an ‘unchangeable’ consonant; no -σ- in genitive). This toy can’t check that—so it just flags ‘likely barytone’.");
  }

  // τραπεζιτης fork
  const bare = stripDiacritics(w);
  if(bare === "τραπεζιτης" || bare === "τραπεζειτης" || bare === "τραπεζητης"){
    cls.note.push("τραπεζίτης fork: ‘market/banker’ is τραπεζίτης (from τράπεζα); ‘dog’ is τραπεζείτης (from τραπεζεύς); poetic variant τραπεζήτης (ει→η). Try toggling spelling below.");
  }

  return cls;
}

function render(){
  const raw = $('#inp').value.trim();
  const ignore = $('#stripAcc').checked;
  const showSyll = $('#showSyll').checked;
  const showRules = $('#showRules').checked;

  if(!raw){
    $('#out').innerHTML = `<div class="warnbox">Type a Greek word ending in <span class="mono">-της</span> (or <span class="mono">-οιτης</span>, <span class="mono">-ουτης</span>, <span class="mono">-υτης</span>), e.g. <span class="mono">Δαμοίτης</span> or <span class="mono">Μαντούτης</span>.</div>`;
    return;
  }

  const inputForAnalysis = ignore ? stripDiacritics(raw) : raw;
  const cls = classify(inputForAnalysis);
  const sug = barytoneSuggest(inputForAnalysis);

  let badges = [];
  if(cls.suffix){
    badges.push(`<span class="badge good">suffix: -${cls.suffix}</span>`);
  } else {
    badges.push(`<span class="badge bad">no -της suffix detected</span>`);
  }
  if(cls.barytone === true) badges.push(`<span class="badge good">barytone (toy)</span>`);
  else if(cls.barytone === false) badges.push(`<span class="badge bad">not barytone</span>`);
  else badges.push(`<span class="badge warn">unknown</span>`);

  const sylHtml = showSyll && sug.syl.length
    ? `<div class="v">${sug.syl.map((s,i)=>`<span class="syll" title="syllable ${i+1}">${s}</span>`).join('')}</div>`
    : `<div class="v"><span class="badge warn">(syllables hidden)</span></div>`;

  // τραπεζιτης switcher
  const bare = stripDiacritics(lowerGreek(inputForAnalysis)).replace(/[^\p{L}]/gu,'');
  let fork = '';
  if(bare.startsWith('τραπεζ') && bare.endsWith('της')){
    const baseStem = 'τραπεζ';
    fork = `
      <div class="hr"></div>
      <div class="kv">
        <div class="k">τραπεζίτης toy fork</div>
        <div class="v">
          <button class="btn ghost" data-fork="τραπεζιτης">τραπεζίτης (ι)</button>
          <button class="btn ghost" data-fork="τραπεζειτης">τραπεζείτης (ει)</button>
          <button class="btn ghost" data-fork="τραπεζητης">τραπεζήτης (η)</button>
          <div class="note">Click to replace your input with one of Herodian’s spellings and re-run.</div>
        </div>
      </div>
    `;
  }

  const notes = showRules ? cls.note.map(n=>`<div class="note">• ${n}</div>`).join('') : '';

  $('#out').innerHTML = `
    <div class="kv">
      <div class="k">Input (as analyzed)</div>
      <div class="v"><span class="mono">${escapeHtml(inputForAnalysis)}</span></div>

      <div class="k">Flags</div>
      <div class="v">${badges.join(' ')}</div>

      <div class="k">Rough syllables</div>
      ${sylHtml}

      <div class="k">“Barytone” suggestion</div>
      <div class="v"><span class="mono">${escapeHtml(sug.suggestion)}</span> <span class="badge warn">accent placed on penult (toy)</span></div>

      <div class="k">Unaccented form</div>
      <div class="v"><span class="mono">${escapeHtml(stripDiacritics(inputForAnalysis))}</span></div>
    </div>
    ${fork}
    ${notes ? `<div class="hr"></div>${notes}` : ''}
  `;

  // bind fork buttons if present
  $('#out').querySelectorAll('button[data-fork]').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const v = btn.getAttribute('data-fork');
      // display with polytonic-ish accents for the three known forms
      const pretty = (v === 'τραπεζιτης') ? 'τραπεζίτης'
        : (v === 'τραπεζειτης') ? 'τραπεζείτης'
        : 'τραπεζήτης';
      $('#inp').value = pretty;
      render();
    });
  });
}

function escapeHtml(s){
  return String(s)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

// --- Generator mini-game ---
const suffixOptions = [
  {id:'ιτης', label:'-ίτης / -ιτης', suf:'ιτης'},
  {id:'ειτης', label:'-είτης / -ειτης', suf:'ειτης'},
  {id:'οιτης', label:'-οίτης / -οιτης', suf:'οιτης'},
  {id:'ουτης', label:'-ούτης / -ουτης', suf:'ουτης'},
  {id:'υτης', label:'-ύτης / -υτης', suf:'υτης'},
  {id:'της', label:'-της', suf:'της'}
];
let chosenSuffix = 'ειτης';

function renderChips(){
  const box = $('#chips');
  box.innerHTML = '';
  for(const opt of suffixOptions){
    const b = document.createElement('button');
    b.className = 'chip';
    b.type = 'button';
    b.textContent = opt.label;
    b.setAttribute('aria-pressed', opt.suf === chosenSuffix ? 'true' : 'false');
    b.addEventListener('click', ()=>{
      chosenSuffix = opt.suf;
      renderChips();
    });
    box.appendChild(b);
  }
}

function generate(){
  const stem = $('#stem').value.trim();
  if(!stem){
    $('#genOut').innerHTML = `<span class="badge bad">Give a stem first.</span>`;
    return;
  }
  const glued = stripDiacritics(stem) + chosenSuffix;
  const sug = barytoneSuggest(glued);
  const cls = classify(glued);

  const ok = cls.suffix ? 'good' : 'warn';
  $('#genOut').innerHTML = `
    <div><span class="badge ${ok}">made</span> <span class="mono">${escapeHtml(glued)}</span></div>
    <div class="tiny">Barytone toy-accent → <span class="mono">${escapeHtml(sug.suggestion)}</span></div>
  `;
}

// --- events ---
$('#btnAnalyze').addEventListener('click', render);
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });
$('#stripAcc').addEventListener('change', render);
$('#showSyll').addEventListener('change', render);
$('#showRules').addEventListener('change', render);
$('#btnClear').addEventListener('click', ()=>{ $('#inp').value=''; render(); });
$('#btnShuffle').addEventListener('click', ()=>{
  const pick = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = pick;
  render();
});
$('#btnGen').addEventListener('click', generate);

renderChips();
render();

